body.script:
(async function () {
  const status = document.getElementById('godly-status');
  const splash = document.getElementById('godly-splash');
  const frame = document.getElementById('godly-viewport');
  const fallbackWrap = document.getElementById('godly-fallback-wrap');

  let dismissed = false;
  function dismiss() {
    if (dismissed) return;
    dismissed = true;
    if (splash) {
      splash.style.opacity = '0';
      setTimeout(() => { splash.style.display = 'none'; }, 450);
    }
  }

  frame.onload = () => {
    setTimeout(dismiss, 400);
  };

  const loc = window.location.href;
  const isJsDelivr = loc.includes('cdn.jsdelivr.net');
  const isWasmer = loc.includes('wasmer.app') || loc.includes('wasmer.io');
  const origin = window.location.origin || '';

  // Handle jsDelivr direct streaming:
  if (isJsDelivr) {
    try {
      let tag = 'v4.5.3';
      const tagMatch = loc.match(/@([^/]+)/);
      if (tagMatch && tagMatch[1] && tagMatch[1] !== 'main') {
        tag = tagMatch[1];
      }
      const baseHref = 'https://cdn.jsdelivr.net/gh/donoEla/Godly-OS-Workspac---Github@' + tag + '/dist/';
      const htmlUrl = baseHref + 'index.html?v=' + tag;

      const res = await fetch(htmlUrl);
      if (res.ok) {
        let html = await res.text();
        // Clean any router or redirect scripts
        html = html.replace(/<script>[\s\S]*?Production Deployment Router[\s\S]*?<\/script>/gi, '');
        html = html.replace(/<noscript>[\s\S]*?<\/noscript>/gi, '');

        // Ensure <base href="..."> is present so all relative JS/CSS/assets resolve to jsDelivr
        if (!html.includes('<base ')) {
          html = html.replace('<head>', '<head>\n    <base href="' + baseHref + '">');
        }
        // Rewrite relative ./ paths to absolute jsDelivr CDN endpoints with cache-buster
        html = html.replace(/(src|href)=["']\.\/([^"']+)["']/gi, function(_, attr, relPath) {
          return attr + '="' + baseHref + relPath + (relPath.includes('?') ? '&' : '?') + 'v=' + tag + '"';
        });

        // Stream directly into iframe. No redirect.
        frame.srcdoc = html;
        setTimeout(dismiss, 1200);
        return;
      }
    } catch (err) {
      console.warn('jsDelivr inline stream error:', err);
    }
  }

  // If on Wasmer:
  if (isWasmer && origin && origin !== 'null') {
    frame.src = origin + '/';
    setTimeout(dismiss, 1200);
    return;
  }

  // If local development or non-jsDelivr:
  if (!isJsDelivr && origin && origin !== 'null' && window.location.protocol.startsWith('http')) {
    frame.src = './dist/';
    setTimeout(dismiss, 1200);
    return;
  }

  // Fallback only if inline streaming was blocked:
  if (status) status.textContent = 'CDN stream blocked. Click below to launch:';
  if (fallbackWrap) fallbackWrap.style.display = 'flex';
  frame.src = 'https://donoela.github.io/Godly-OS-Workspac---Github/';
  setTimeout(dismiss, 3500);
})();
